#!/usr/bin/env python
"""CLI application with pyproject.toml configuration support."""

import cyclopts
from pathlib import Path

def load_config():
    """Load configuration from [tool.mycli] in pyproject.toml."""
    config_path = Path("pyproject.toml")
    if not config_path.exists():
        return {}

    try:
        import tomllib
    except ImportError:
        import tomli as tomllib

    with open(config_path, "rb") as f:
        data = tomllib.load(f)

    return data.get("tool", {}).get("mycli", {})

# Load configuration once at startup
config = load_config()

# Create CLI app
app = cyclopts.App()

@app.default
def main(
    name: str = cyclopts.Parameter(
        default=config.get("name", "World"),
        help="Name to greet",
    ),
    greeting: str = cyclopts.Parameter(
        default=config.get("greeting", "Hello"),
        help="Greeting message",
    ),
    count: int = cyclopts.Parameter(
        default=config.get("count", 1),
        help="Number of times to repeat",
    ),
    verbose: bool = cyclopts.Parameter(
        default=config.get("verbose", False),
        help="Enable verbose output",
    ),
) -> None:
    """
    Greeting CLI application.

    Configuration defaults are read from [tool.mycli] in pyproject.toml.
    Command-line arguments override configuration file values.
    """
    for i in range(count):
        if verbose:
            print(f"[{i + 1}] {greeting}, {name}!")
        else:
            print(f"{greeting}, {name}!")

if __name__ == "__main__":
    app()

